/**
 * Facts extracted from private gameplay captures (colosseum-no-sol-packet-data.txt, colosseum-waves-bees-death(no-sol)-packet-data-1.txt, colosseum-waves-1-12-damage-trials-solarflare3-volatility3-bees1-totemic-doom1-death-packet-data.txt).
 * Fremennik warband members (npc 12814-12816) in three Colosseum runs, keyed noSol, bees and waves.
 * Tiles are relative to the Colosseum arena origin (world 1792, 3072), except thrall tiles, which keep
 * world `"x,y"` keys and are only compared with each other.
 *
 * `WARBAND_CAPTURE_FRAMES` has one frame per capture tick on which a member was present: the local player's start-of-tick tile, each
 * member update (op, NPC index and type, tile, destination, printed steps, headbar fill, splat values
 * and sequence ids), every archer (9) or seer (130) projectile record (spotanim id and source tile), the player's
 * thralls by tile, and each thrall projectile's source tile and target NPC index.
 *
 * `WARBAND_CAPTURE_PROJECTILES` has every archer (9) and seer (130) projectile at the player: its
 * fields, source and target tiles, and the player's slot-2 spotanim on that tick as
 * `[id, delay, height]`.
 */
import type { Coordinate } from '../../../../types/simulation';

export interface WarbandEvent {
  readonly kind: string;
  readonly index: number;
  readonly npcId: number;
  readonly coord: Coordinate;
  readonly newCoord: Coordinate | null;
  readonly steps: readonly string[];
  readonly fill?: number;
  readonly seqs: readonly number[];
  readonly hits: readonly number[];
}

export interface WarbandFrame {
  readonly tick: number;
  readonly playerStart: Coordinate | null;
  readonly events: readonly WarbandEvent[];
  readonly projectiles: readonly { readonly id: number; readonly source: Coordinate | null }[];
  readonly thralls: readonly (readonly [tile: string, index: number])[];
  readonly thrallShots: readonly { readonly source: string | null; readonly target: number | null }[];
}

export interface WarbandProjectile {
  readonly tick: number;
  readonly fields: {
    readonly spotAnimId: number;
    readonly startDelayCycles: number;
    readonly endDelayCycles: number;
    readonly slope: number;
    readonly startOffset: number;
    readonly startHeight: number;
    readonly endHeight: number;
  };
  readonly source: Coordinate;
  readonly target: Coordinate;
  readonly playerSlot2Spotanim: readonly [id: number, delay: number, height: number] | null;
}

